    marks: [
      Plot.lineY(dat3, {x: "x", y: "p", stroke: "black"}),
      Plot.areaY(dat3, {x: "x", y: v, fill: c, fillOpacity: 0.5}),
      Plot.lineY(dat3, {x: "x", y: v, stroke: c})
    ]
  });
}

plot_list = Object.values(colormap).map(x => density_plot(x.v, x.c))

