```{.r .cell-code}
library(ggplot2)

KL_skew <- function(la) {
  alpha <- exp(la)
  c1 <- (log(2 * pi) + 1) / 2
  c2 <- alpha - log(alpha) / 2 + lgamma(alpha) + (1 - alpha) * digamma(alpha)
  c1 - c2
}

dKL_skew <- function(la) {
  alpha <- exp(la)
  c1 <- 1 / (2 * alpha) - 1
  c2 <- digamma(alpha) * (1 - 1 / gamma(alpha))
  c3 <- (1 - alpha) * trigamma(alpha)
  alpha * (c1 + c2 - c3)
}

find_alpha <- function(c, x0 = 0, xmin = -20, xmax = 20, tolerance = 1e-5, maxIterations = 1000) {
  fmin <- KL_skew(xmin) - c
  fmax <- KL_skew(xmax) - c

  if (sign(fmin) == sign(fmax)) {

    if (abs(fmin) < abs(fmax)) return(xmin) else return(xmax)

  } else {

    x <- x0
    iter <- 0
    error <- Inf

    while (error > tolerance && iter < maxIterations) {
      fx <- KL_skew(x) - c
      dfx <- dKL_skew(x)
      xNext <- x - fx / dfx
      error <- abs(fx)
      x <- xNext
      iter <- iter + 1L
    }

    if (iter == maxIterations) warning("Newton-Raphson method did not converge within the maximum number of iterations.")

    return(x)
  }
}

KL_skew(-10)
```

